			{
			   image->meta->iptc_len = uuid->len;
			   image->meta->iptc_buf = new uint8_t[uuid->len];
			   memcpy(image->meta->iptc_buf, uuid->buf, uuid->len);
			}
		 }
		 else if(memcmp(uuid->uuid, XMP_UUID, 16) == 0)
