			 info_i.asoc != GRK_CHANNEL_ASSOC_UNASSOCIATED))
		 {
			Logger::logger_.error(
				"CDEF box : channels %u and %u share same type/association pair (%u,%u).",
				info_i.channel, info_j.channel, info_j.typ, info_j.asoc);
			goto cleanup;
		 }
	  }
